@startuml

class University {
  + TotalEmployees : int
}

class Faculty {
  + Name : string
}

class Institute {
  + Name : string
  + Address : string
}

class Employee {
  + SocialSecurityNumber : string
  + Name : string
  + EmailAddress : string
}

class ResearchAssistant extends Employee {
  + ResearchField : string
}

class AdministrativeStaff extends Employee {}

class Lecturer extends ResearchAssistant {}

class Course {
  + ID : int
  + Name : string
  + WeeklyDuration : int
}

class Project {
  + Name : string
  + StartDate : date
  + EndDate : date
}

class RAProjectInvolvement {
  + Hours : int
}

University "1" -- "*" Faculty
University "1" -- "*" Employee
Faculty "1" -- "*" Institute
Faculty "1" -- "0..1" Employee : dean

ResearchAssistant "*" -- "1..*" Institute
ResearchAssistant "1" -- "*" RAProjectInvolvement
RAProjectInvolvement "*" -- "1" Project
Lecturer "1" -- "*" Course

@enduml

